/**
 * @param {number} n
 * @param {number[]} costs
 * @return {number}
 */
var climbStairs = function(n, costs) {
    const dp = Array(n + 1).fill(Infinity);

    const climb = (pos, cost) => {
        if (pos > n) return Infinity;
        if (pos === n) return cost;
        if (dp[pos] < Infinity && dp[pos] <= cost) return dp[pos];

        const min = Math.min(
            climb(pos + 3, cost + (costs[pos + 2] ?? Infinity) + 9),
            climb(pos + 2, cost + (costs[pos + 1] ?? Infinity) + 4),
            climb(pos + 1, cost + costs[pos] + 1),
        );

        dp[pos] = min;
        return dp[pos];
    };

    return climb(0, 0);
};

