var climbStairs = function(n, costs) {
    const dp = Array(n + 1).fill(Infinity);
    dp[n] = 0;

    for (let i = n; i >= 1; i--) {
        dp[i - 1] = Math.min(dp[i - 1], dp[i] + costs[i - 1] + 1);
        if (i >= 2) dp[i - 2] = Math.min(dp[i - 2], dp[i] + costs[i - 1] + 4);
        if (i >= 3) dp[i - 3] = Math.min(dp[i - 3], dp[i] + costs[i - 1] + 9);
    }

    return dp[0];
};

